@pytest.mark.parametrize(("cost_deltas", "spend_budget", "waiver_credits", "expected"), FURTHEST_MONTH_ORACLES)
def test_furthest_month_oracles(cost_deltas, spend_budget, waiver_credits, expected):
    assert furthest_month(cost_deltas, spend_budget, waiver_credits) == expected


@pytest.mark.parametrize(("cost_deltas", "spend_budget", "waiver_credits", "expected"), MORE_FURTHEST_MONTH_ORACLES)
def test_furthest_month_extended_oracles(cost_deltas, spend_budget, waiver_credits, expected):
    assert furthest_month(cost_deltas, spend_budget, waiver_credits) == expected


def reference_furthest_month(cost_deltas, spend_budget, waiver_credits):
    def reachable(prefix_length):
        prefix = cost_deltas[:prefix_length]
        for mask in range(1 << len(prefix)):
            waived = 0
            spent = 0
            for i, delta in enumerate(prefix):
                if mask & (1 << i):
                    waived += 1
                else:
                    spent += max(delta, 0)
            if waived <= waiver_credits and spent <= spend_budget:
                return True
        return False

    length = 0
    while length < len(cost_deltas) and reachable(length + 1):
        length += 1
    return length


def test_matches_an_exhaustive_subset_search_for_every_small_input():
    for length in range(6):
        for cost_deltas in itertools.product([-1, 0, 1, 2, 3], repeat=length):
            cost_deltas = list(cost_deltas)
            for spend_budget in range(7):
                for waiver_credits in range(4):
                    assert furthest_month(cost_deltas, spend_budget, waiver_credits) == reference_furthest_month(
                        cost_deltas, spend_budget, waiver_credits
                    ), (cost_deltas, spend_budget, waiver_credits)


def test_never_mutates_the_input_array():
    cost_deltas = [4, 2, 7, 6, 9, 14, 12]
    furthest_month(cost_deltas, 5, 1)
    assert cost_deltas == [4, 2, 7, 6, 9, 14, 12]


def test_more_budget_or_more_waivers_never_reach_a_shorter_month():
    cost_deltas = [4, 12, 2, 7, 3, 18, 20, 3, 19]
    for waivers in range(5):
        previous = -1
        for budget in range(61):
            month = furthest_month(cost_deltas, budget, waivers)
            assert month >= previous, (budget, waivers)
            previous = month
    for budget in range(0, 61, 5):
        previous = -1
        for waivers in range(10):
            month = furthest_month(cost_deltas, budget, waivers)
            assert month >= previous, (budget, waivers)
            previous = month


def test_enough_waivers_always_reach_the_end():
    cost_deltas = [5, 9, 1, 20, 3, 8]
    assert furthest_month(cost_deltas, 0, len(cost_deltas)) == len(cost_deltas)
